use pgweave_ast::ddl::ReturnType;
use pgweave_ast::types::DataType;
use pgweave_ast::{DdlStatement, Statement};
use pgweave_schema::provider::object_name_to_string;
use pgweave_semantic::{OutputColumn, SemanticResult};

/// Generate TypeScript interface declarations from SQL statements + semantic analysis.
///
/// Output format:
/// ```ts
/// // Generated by pgweave — do not edit manually
/// export interface ProjectSummaryRow {
///   total_tasks: number;
///   completion_rate: number;
/// }
/// ```
pub fn generate_ts_types(sql: &str, stmts: &[Statement], semantic: &SemanticResult) -> String {
    let mut out = String::from("// Generated by pgweave — do not edit manually\n\n");
    let mut generated_any = false;

    // ── Named queries via -- @name: InterfaceName ────────────────────────────
    // Parse the original SQL source for @name annotations
    let named_queries = extract_named_queries(sql);

    for (name, select_idx) in &named_queries {
        // Find the select_idx-th SELECT statement in the semantic select_columns
        let cols_by_order: Vec<_> = semantic.select_columns.values().collect();
        // HashMap ordering is not stable, but we index into whatever order we get.
        // This is a best-effort heuristic; for accurate results use NodeId ordering.
        if let Some(cols) = cols_by_order.get(*select_idx) {
            out.push_str(&render_interface(name, cols));
            out.push('\n');
            generated_any = true;
        }
    }

    // ── CREATE FUNCTION RETURNS TABLE ────────────────────────────────────────
    for stmt in stmts {
        if let Statement::Ddl(DdlStatement::CreateFunction(cf)) = stmt {
            let fn_name = object_name_to_string(&cf.name);
            match &cf.return_type {
                ReturnType::Table(cols) => {
                    // cols: Vec<(Ident, DataType)>
                    let interface_name = to_pascal_case(&fn_name) + "Row";
                    let items: Vec<OutputColumn> = cols
                        .iter()
                        .map(|(ident, dt)| OutputColumn {
                            name: Some(ident.value.clone()),
                            data_type: dt.clone(),
                            node_id: pgweave_ast::NodeId::DUMMY,
                        })
                        .collect();
                    out.push_str(&render_interface(&interface_name, &items));
                    out.push('\n');
                    generated_any = true;
                }
                ReturnType::SetOf(DataType::Custom(type_name)) => {
                    // RETURNS SETOF some_type — emit a minimal marker comment
                    let interface_name = to_pascal_case(&fn_name) + "Result";
                    out.push_str(&format!(
                        "// {} returns SETOF {} — define the type manually\n",
                        fn_name, type_name
                    ));
                    out.push_str(&format!(
                        "export type {} = {};\n\n",
                        interface_name,
                        to_pascal_case(type_name)
                    ));
                    generated_any = true;
                }
                _ => {}
            }
        }
    }

    if !generated_any {
        out.push_str("// No named queries or typed functions found.\n");
        out.push_str("// Use -- @name: InterfaceName before SELECT queries,\n");
        out.push_str("// or define functions with RETURNS TABLE(...).\n");
    }

    out
}

/// Convenience function: parse + analyze + generate from a SQL string.
/// Returns the TypeScript source, or an error message.
pub fn generate_ts_types_from_sql(sql: &str) -> String {
    let stmts = match pgweave_parser::parse(sql) {
        Ok(s) => s,
        Err(e) => return format!("// parse error: {}\n", e),
    };
    let schema = pgweave_catalog::ProjectCatalog::from_statements(&stmts);
    let semantic = pgweave_semantic::analyze(&stmts, &schema);
    generate_ts_types(sql, &stmts, &semantic)
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/// Render a TypeScript interface for a list of output columns.
fn render_interface(name: &str, cols: &[OutputColumn]) -> String {
    let mut s = format!("export interface {} {{\n", name);
    for col in cols {
        let field_name = col.name.as_deref().unwrap_or("_unknown");
        let ts_type = col.ts_type();
        s.push_str(&format!("  {}: {};\n", field_name, ts_type));
    }
    s.push_str("}\n");
    s
}

/// Extract named queries from SQL source.
/// Looks for "-- @name: InterfaceName" comment lines immediately followed by a SELECT.
/// Returns Vec<(interface_name, select_index)> where select_index is 0-based
/// index among all SELECT statements in the file.
fn extract_named_queries(sql: &str) -> Vec<(String, usize)> {
    let mut result = Vec::new();
    let lines: Vec<&str> = sql.lines().collect();
    let mut select_idx = 0usize;
    let mut i = 0;

    while i < lines.len() {
        let trimmed = lines[i].trim();
        if let Some(name) = trimmed.strip_prefix("-- @name:").map(str::trim) {
            // Next non-empty line should be SELECT
            let mut j = i + 1;
            while j < lines.len() && lines[j].trim().is_empty() {
                j += 1;
            }
            if j < lines.len()
                && lines[j]
                    .trim_start()
                    .to_ascii_uppercase()
                    .starts_with("SELECT")
            {
                result.push((name.to_string(), select_idx));
            }
        }
        // Count SELECT keywords at statement start (rough heuristic)
        if trimmed.to_ascii_uppercase().starts_with("SELECT") {
            select_idx += 1;
        }
        i += 1;
    }
    result
}

/// Convert snake_case → PascalCase.
pub fn to_pascal_case(s: &str) -> String {
    s.split('_')
        .filter(|p| !p.is_empty())
        .map(|p| {
            let mut c = p.chars();
            match c.next() {
                None => String::new(),
                Some(f) => f.to_uppercase().to_string() + c.as_str(),
            }
        })
        .collect()
}
